import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第四册：流利英语 · Lesson 26 The past life of the earth","description":"学习 完成式分词状语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 26 The past life of the earth","description":"学习 完成式分词状语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 完成式分词状语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 25 Non-auditory effects of noise","link":"/life/english/new-concept/book-4/unit-04/lesson-025"},"next":{"text":"第四册：流利英语 · Lesson 27 The 'Vasa'","link":"/life/english/new-concept/book-4/unit-04/lesson-027"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 25 Non-auditory effects of noise","link":"/life/english/new-concept/book-4/unit-04/lesson-025"},"next":{"text":"第四册：流利英语 · Lesson 27 The 'Vasa'","link":"/life/english/new-concept/book-4/unit-04/lesson-027"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-026.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-026.md"}`),i={name:"life/english/new-concept/book-4/unit-04/lesson-026.md"};function s(r,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-26-the-past-life-of-the-earth" tabindex="-1">第四册：流利英语 · Lesson 26 The past life of the earth <a class="header-anchor" href="#第四册-流利英语-·-lesson-26-the-past-life-of-the-earth" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 26 The past life of the earth&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过地球过去生命的主题训练深时间阅读，区分岩层相对顺序、证据保存偏差和具体年代判断。不能把没有找到某种化石直接等同于该生物从未存在。重点用完成时分词组织先后关系，说明研究过程时保留观测与解释的分界。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>stratum</td><td>/ˈstrɑːtəm/</td><td>n.</td><td>地层</td><td>a rock stratum</td></tr><tr><td>sequence</td><td>/ˈsiːkwəns/</td><td>n.</td><td>顺序</td><td>a geological sequence</td></tr><tr><td>extinction</td><td>/ɪkˈstɪŋkʃən/</td><td>n.</td><td>灭绝</td><td>a mass extinction</td></tr><tr><td>preservation</td><td>/ˌprezəˈveɪʃən/</td><td>n.</td><td>保存</td><td>fossil preservation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>leave behind — 留下痕迹</li><li>in relation to — 相对于某对象</li></ul><h2 id="语法讲解-完成式分词状语" tabindex="-1">语法讲解：完成式分词状语 <a class="header-anchor" href="#语法讲解-完成式分词状语" aria-label="Permalink to &quot;语法讲解：完成式分词状语&quot;">​</a></h2><p>Having examined the layers, the team proposed a sequence. 中 having done 表示检查发生在提出之前，并与主句共享主语。若对象被检查，可用 having been examined，但要确保逻辑主语是被检查物。完成式分词突出先完成某事再做另一事，不必对所有有先后顺序的动作都使用。主语不一致时，用 after 引导完整从句更清楚，避免因压缩而造成悬垂修饰。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Having compared the layers, the researchers proposed a tentative sequence of events.</p></blockquote><p>比较地层之后，研究者提出了一个暂定的事件顺序。</p><p>Having compared 表先行完成动作；researchers 同时是 compare 和 propose 的执行者；tentative 限定结论。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Having compared the layers, a sequence was proposed 容易让 sequence 成为比较者；应明确主语 researchers。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 Having compared the layers 连读为前置信息，主句重读 tentative；不要把 having 单独读成一句。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Having compared the samples, we placed layer B below layer A in our working sequence. This interpretation remains provisional. Some evidence may have been lost through erosion.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句汇报虚构岩层比较，包含前置完成动作、初步结论和保存局限。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>完成式交代研究顺序，后两句说明暂定性和证据缺失来源。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中比较与提出哪个在先？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 比较在先。</p><p><strong>解析：</strong> having compared 标记先完成的动作。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：Having ___ the records, she revised the timeline.（check）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> checked</p><p><strong>解析：</strong> 完成式分词结构为 having + 过去分词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>没有发现化石能直接证明从未有生命吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 保存和发现过程可能留下缺口。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：完成式分词状语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-025">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-027">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",s]]);export{u as __pageData,f as default};
